from collections import Counter
def f(inp):
    h=len(inp); w=len(inp[0])
    cnt=Counter(v for r in inp for v in r)
    # ring color: a color whose cells include some rectangle perimeter; prefer fully-closed rectangles
    def ring_of(col):
        cells={(r,c) for r in range(h) for c in range(w) if inp[r][c]==col}
        rs=[r for r,_ in cells]; cs=[c for _,c in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        per={(r,c) for r in range(r0,r1+1) for c in (c0,c1)}|{(r,c) for r in (r0,r1) for c in range(c0,c1+1)}
        if len(cells)>=per and len(cells)>len(per)/2:  # contains its perimeter -> likely a ring around extras inside or the ring itself
            return r0,r1,c0,c1,col
        return None
    for col in sorted(cnt,key=cnt.get,reverse=True):
        rr=ring_of(col)
        if rr and rr[3]-rr[0]>=3 and rr[4]-rr[1]>=3:
            fr,far,fc,fcc,rcol=rr; break
    else:
        # fallback: largest rectangle by area containing another color on its perimeter set
        res=None
        for r0 in range(h):
            for r1 in range(r0,h):
                for c0 in range(w):
                    for c1 in range(c0,w):
                        per=set((r,c) for r in range(r0,r1+1) for c in (c0,c1))|set((r,c) for c in range(c0,c1+1) for r in (r0,r1))
                        if any(inp[r][c]!=0 for r,c in per): continue
                        cols={inp[r][c] for r in range(r0,r1+1) for c in range(c0,c1+1)}-{0}
                        if len(cols)==1:
                            a=(r1-r0)*(c1-c0)
                            if res is None or a>res[0]: res=(a,cols.pop(),r0,r1,c0,c1)
        _,col,fr,far,fc,fcc=res
    ih,iw=far-fr-1,fcc-fc-1
    bg=cnt.most_common(1)[0][0]
    rest=[(r,c,inp[r][c]) for r in range(h) for c in range(w) if inp[r][c] not in (0,col)]
    mr=min(r for r,_,_ in rest); mc=min(c for _,c,_ in rest)
    rh=max(r-mr for r,_,_ in rest)+1; rw=max(c-mc for _,c,_ in rest)+1
    s=min(ih//rh,iw//rw)
    out=[[bg]*(s*rw+2) for _ in range(s*rh+2)]
    for i in range(1,s*rh+1):
        for j in range(1,s*rw+1):
            dr=(i-1)//s; dc=(j-1)//s
            v=next((vv for r,c,vv in rest if r-mr==dr and c-mc==dc),bg)
            out[i][j]=v
    return out

