        per={(r,cc) for r in range(r0,r1+1) for cc in (c0,c1)}|{(r,cc) for r in (r0,r1) for cc in range(c0,c1+1)}
        if cells==per and (r1-r0)>=2 and (c1-c0)>=2:
            area=(r1-r0)*(c1-c0)
            if best is None or area>best[0]: best=(area,c,r0,r1,c0,c1)
    col,r0,r1,c0,c1=best[1:]
    ih,iw=r1-r0-1,c1-c0-1
