    rh=max(r-mr for r,_,_ in rest)+1; rw=max(cc-mc for _,cc,_ in rest)+1
    bg=cnt.most_common(1)[0][0]
    s=min(ih//rh,iw//rw)
    out=[[col]*(s*rw+2) for _ in range(s*rh+2)]
    for i in range(1,s*rh+1):
        for j in range(1,s*rw+1):
            dr=(i-1)//s; dc=(j-1)//s
            v=next((vv for r,cc,vv in rest if r-mr==dr and cc-mc==dc),bg)
